import { Component, Input, OnChanges, OnInit } from '@angular/core';
import { Icon } from '@shared/constants/icons.constants';
import { AbstractComponent } from '@shared/component/abstract-component/abstract-component';

import { SharedImplementationModule } from '@shared/shared-implementation.module';


@Component({
	selector: 'app-icon',
	templateUrl: './icon.component.html',
	styleUrls: ['./icon.component.scss'],
	imports: [SharedImplementationModule]
})
export class IconComponent extends AbstractComponent {
	@Input() icon: string = Icon.QUESTION;
	@Input() size: string = '1x';
	@Input() preset: 'checkmark' | 'error' | 'default' = 'default';
	public readonly Icon = Icon;

	constructor() {
		super();
	}

	getSize(): string {
		const sizeDefinedWithX = /\d+x/;
		return sizeDefinedWithX.test(this.size) ? this.size.replace('x', 'rem') : this.size;
	}

}
