import { Injectable, Signal, signal, WritableSignal } from '@angular/core';
import { AuthService } from '@core/service/auth.service';
import { CommonUtil } from '@core/util';
import { NAV_ITEMS } from '@core/navigation/sidebar.constant';
import { hasPermission, Permission } from '@model/common/permission.model';
import { NavItem } from '@core/navigation/sidebar.model';
import { BehaviorSubject, Subject } from 'rxjs';

@Injectable({
	providedIn: "root"
})
export class NavItemService {
	private userPermissions: Permission[];
	private isAuthenticated: boolean;
	private readonly navItemsUpdatedSubject: BehaviorSubject<NavItem[]> = new BehaviorSubject<NavItem[]>([]);

	constructor(private readonly authService: AuthService) {
		this.authService.getUserAuthenticatedSubject().subscribe(authenticated => {
			this.userPermissions = this.authService.getUserPermissions();
			this.isAuthenticated = authenticated;
			this._navItems.set(this.resolveNavItems());
			this._hasAnyNavItem.set(!!this.getNavItems().length)
			this.navItemsUpdatedSubject.next(this.getNavItems());
		})
	}

	private readonly _hasAnyNavItem: WritableSignal<boolean> = signal(true);
	readonly hasAnyNavItem: Signal<boolean> = this._hasAnyNavItem;

	private readonly _navItems: WritableSignal<NavItem[]> = signal([]);
	readonly getNavItems: Signal<NavItem[]> = this._navItems;

	private resolveNavItems(): NavItem[] {
		return CommonUtil.deepClone(NAV_ITEMS.filter(item => {
			if (item.allowUnauthenticatedAccess) {
				return true;
			} else if (item.requiredPermissions?.length) {
				return hasPermission(this.userPermissions, item.requiredPermissions);
			}
			return this.isAuthenticated;
		}));
	}

	getNavItemsUpdatedSubject(): Subject<NavItem[]> {
		return this.navItemsUpdatedSubject;
	}

}