import { Component, computed, EventEmitter, input, InputSignal, Output, Signal, signal, WritableSignal } from '@angular/core';
import { Route } from '@app/shared/constants/routing-paths.constants';
import { AuthService } from '@core/service/auth.service';
import { Router } from '@angular/router';
import { Store } from '@ngrx/store';
import { fromAuthActions } from '@store/actions/actions';
import { AbstractComponent } from '@shared/component/abstract-component/abstract-component';
import { ThemeIcon } from '@shared/component/toolbar/toolbar.model';
import { SharedImplementationModule } from '@shared/shared-implementation.module';
import { ThemeService } from '@core/service/theme.service';
import { ThemeKey, Themes, ThemeValue } from '@model/common/theme.model';
import { CommonUtil } from '@core/util';
import { NavItemService } from '@core/service/nav-item.service';

@Component({
  selector: 'app-toolbar',
  templateUrl: './toolbar.component.html',
  styleUrls: ['./toolbar.component.scss'],
	imports: [SharedImplementationModule]
})
export class ToolbarComponent extends AbstractComponent {
	protected readonly Route = Route;
	protected isAuthenticated: boolean = false;
	protected readonly currentTheme: WritableSignal<ThemeValue> = signal(ThemeService.getCurrentTheme());
	protected readonly nextTheme: Signal<ThemeValue> = computed(() => {
		const currentTheme = this.currentTheme();
		const themeValues = Object.values(Themes);
		const currentThemeIndex = themeValues.indexOf(currentTheme);
		const nextThemeIndex = currentThemeIndex + 1 < themeValues.length ? currentThemeIndex + 1 : 0;
		return themeValues[nextThemeIndex];
	});
	protected readonly nextThemeIcon: Signal<string> = computed(() => {
		const currentThemeKey: ThemeKey = CommonUtil.getKeyByValue(Themes, this.currentTheme());
		return ThemeIcon[currentThemeKey] ?? ThemeIcon[0];
	});
	protected readonly themes: WritableSignal<ThemeValue[]> = signal([...Object.values(Themes)]);

	constructor(private readonly authService: AuthService,
							private readonly router: Router,
							private readonly store: Store,
							private readonly navItemService: NavItemService,
							private readonly themeService: ThemeService) {
		super();
		this.authService.getUserAuthenticatedSubject().subscribe((isAuthenticated: boolean) => {
			this.isAuthenticated = isAuthenticated;
		});
	}
	showAppName: InputSignal<boolean> = input(true);
	hasAnyNavItem: Signal<boolean> = this.navItemService.hasAnyNavItem;
	showSidebarButton: InputSignal<boolean> = input(true);

	@Output() toggleClick: EventEmitter<void> = new EventEmitter<void>();

	onToggleClick(): void {
		this.toggleClick.emit();
	}

	login(): void {
		this.router.navigate([Route.LOGIN]);
	}

	viewNotifications(): void {
		// TODO: Implement
	}

	register(): void {
		this.router.navigate([Route.REGISTER]);
	}

	logout(): void {
		this.store.dispatch(fromAuthActions.logout());
	}

	updateTheme(): void {
		const nextTheme = this.nextTheme();
		this.currentTheme.update(() => nextTheme);
		this.themeService.setTheme(nextTheme);
	}

}
