import { Injectable } from '@angular/core';
import { AbstractControl } from '@angular/forms';
import { ValidationErrorKeys } from '@shared/service/validation.models';



@Injectable({
	providedIn: 'root'
})
export class ValidationService {


	public static getValidationErrorMessage(validationError: ValidationErrorValue, customLiterals?: { [key: string]: string }): string {
		const validationErrorKey: string = validationError ? Object.keys(validationError)[0] : undefined;

		if (customLiterals?.[validationErrorKey]) {
			return customLiterals?.[validationErrorKey];
		}

		const config: Partial<{ [key in ValidationErrorKeys]: string }> = {
			required: 'Obligatoriskt fält',
			maxlength: `Fältet får som mest ha ${validationError.requiredLength} karaktärer`,
			minlength: `Fältet måste minst ha  ${validationError.requiredLength} karaktärer`
		};

		return Object.keys(config).includes(validationErrorKey) ? config[validationErrorKey as ValidationErrorKeys] : 'Ogiltigt format';
	}

	public static passwordValidator(control: AbstractControl): PasswordCreationValidationError | null {
		const value: string | undefined = control?.value?.toString();
		if (!value) {
			return undefined;
		}
		const errors: PasswordCreationValidationError = {};

		const minLength = 6;
		if (value.length < minLength) {
			errors.minLength = `Password length is greater than ${minLength} characters`;
		}

		const maxLength = 64;
		if (value.length > maxLength) {
			errors.maxLength = `Password length is less than ${maxLength} characters`;
		}

		const specialCharacters = '!@#$%^&*[]:.,'
		const specialCharactersPattern = new RegExp(`.*[${specialCharacters}]+.*`);
		if (!specialCharactersPattern.test(value)) {
			errors.specialCharacter = `Contains at least one special characters of the following: ${specialCharacters}`
		}

		if (new RegExp(`.*[a-z]+.*`).test(value)) {
			errors.lowercaseCharacter = 'Includes at least one lowercase character';
		}

		if (new RegExp(`.*[A-Z]+.*`).test(value)) {
			errors.uppercaseCharacter = 'Includes at least one uppercase character';
		}

		if (new RegExp(`.*[0-9]+.*`).test(value)) {
			errors.digit = 'Includes at least one digit';
		}

		return Object.keys(errors).length ? errors : null;
	}
}

export interface PasswordCreationValidationError {
	minLength?: string;
	maxLength?: string;
	digit?: string;
	lowercaseCharacter?: string;
	uppercaseCharacter?: string;
	specialCharacter?: string;
}

export interface LengthValidationError {
	requiredLength: number;
	actualLength: number;
}

export type ValidationErrorValue = LengthValidationError | { [key: string]: any }
