import { AfterViewInit, ChangeDetectorRef, Component, ElementRef, input, InputSignal, OnDestroy, ViewChild } from '@angular/core';
import { AbstractComponent } from '@shared/component/abstract-component/abstract-component';
import { SharedImplementationModule } from '@shared/shared-implementation.module';
import { PlaceholderImageQuality } from '@angular/youtube-player';
import { debounce } from 'lodash-es';

@Component({
  selector: 'app-youtube-player',
  templateUrl: './youtube-player.component.html',
  styleUrls: ['./youtube-player.component.scss'],
	imports: [SharedImplementationModule]
})
export class YouTubePlayerComponent extends AbstractComponent implements AfterViewInit, OnDestroy {
	private observer: ResizeObserver;

	protected wrapperWidth: number | undefined;
	protected wrapperHeight: number | undefined;

	protected videoWidth: number | undefined;
	protected videoHeight: number | undefined;

	videoId: InputSignal<string> = input.required();
	placeholderImageQuality: InputSignal<PlaceholderImageQuality> = input('high' as PlaceholderImageQuality);
	disablePlaceholder: InputSignal<boolean> = input(false);

	@ViewChild('wrapper') wrapper: ElementRef<HTMLDivElement>;
	@ViewChild('youtubePlayer') youtubePlayer: ElementRef<HTMLDivElement>;

	constructor(private changeDetectorRef: ChangeDetectorRef) {
		super();
	}

	setUpResizeObserver(): void {
		this.observer = new ResizeObserver(debounce((entries) => {
			this.onResize();
		}));

		this.observer.observe(this.wrapper.nativeElement);
	}

	ngAfterViewInit(): void {
		this.setUpResizeObserver();
	}

	onResize(): void {
		const target: any = this.wrapper.nativeElement;
		console.log(target);
		this.wrapperWidth = target?.clientWidth;
		this.wrapperHeight = target?.clientHeight;

		// you can remove this line if you want to have wider video player than 1200px
		this.videoWidth = this.wrapperWidth;
		// To keep the aspect ratio
		this.videoHeight = this.videoWidth * 0.6;
		this.changeDetectorRef.detectChanges();
	}

	ngOnDestroy() {
		this.observer.unobserve(this.wrapper.nativeElement);
	}

}
