import { AuthStatus } from './auth/auth.model';

export enum ExecutionStatus {
	SUCCESS = 'SUCCESS',
	VALIDATION_ERROR = 'VALIDATION_ERROR',
	INVALID_HTTP_METHOD = 'INVALID_HTTP_METHOD',
	TOO_MANY_REQUESTS = 'TOO_MANY_REQUESTS',
	INTERNAL_SERVER_ERROR = 'INTERNAL_SERVER_ERROR'
}

export type ResponseStatus = AuthStatus | ExecutionStatus;

export function mapStatusToHttpCode(status: ResponseStatus): number {
	const asAuthStatus: AuthStatus | undefined = status as AuthStatus;
	if (asAuthStatus) {
		return mapAuthStatusToHttpCode(asAuthStatus);
	}

	const asExecutionStatus: ExecutionStatus | undefined = status as ExecutionStatus;
	if (asExecutionStatus) {
		return mapExecutionStatusToHttpCode(asExecutionStatus);
	}

	console.error(`Unmappable status [${status}] encountered`);
	return 500;
}

export function mapExecutionStatusToHttpCode(executionStatus: ExecutionStatus): number {
	switch (executionStatus) {
		case ExecutionStatus.SUCCESS:
			return 200;
		case ExecutionStatus.VALIDATION_ERROR:
			return 400;
		case ExecutionStatus.TOO_MANY_REQUESTS:
			return 409;
		case ExecutionStatus.INVALID_HTTP_METHOD:
			return 405;
		case ExecutionStatus.INTERNAL_SERVER_ERROR:
			return 500;
		default:
			console.error(`Unmappable authentication status [${executionStatus}] encountered`);
			return 500;
	}
}

export function mapAuthStatusToHttpCode(authStatus: AuthStatus): number {
	switch (authStatus) {
		case AuthStatus.VALID_AUTH:
			return 200;
		case AuthStatus.INVALID_AUTH:
			return 401;
		case AuthStatus.INSUFFICIENT_PERMISSIONS:
			return 403;
		case AuthStatus.ERROR:
			return 500;
		default:
			console.error(`Unmappable authentication status [${authStatus}] encountered`);
			return 500;
	}
}

export function createErrorResponse(status: ResponseStatus, message?: string): ErrorResponse {
	return {
		status,
		message
	};
}

/**
 * Common fields for the API responses? But them here!
 */
export interface ApiResponse {
	status?: ResponseStatus;
	message?: string;
}

export interface ErrorResponse extends ApiResponse {
	message?: string;
}