import { Injectable, Renderer2, RendererFactory2 } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { BoundedLocalStorage } from '@core/service/local-storage.service';
import { asTheme, Themes, THEME_CSS_PREFIX, ThemeValue, ThemeProvider, Theme } from '@model/common/theme.model';
import { LocalStorageKey } from '@shared/constants/local-storage.constants';


@Injectable({
	providedIn: 'root'
})
export class ThemeService {
	private static readonly STORAGE: BoundedLocalStorage<ThemeValue> = BoundedLocalStorage.create(LocalStorageKey.THEME);
	private readonly theme$: BehaviorSubject<ThemeValue>;
	private readonly renderer: Renderer2;

	constructor(rendererFactory: RendererFactory2) {
		this.renderer = rendererFactory.createRenderer(null, null);
		this.theme$ = new BehaviorSubject<ThemeValue>(ThemeService.getCurrentTheme());
		this.setTheme(this.theme$.value, false);
	}

	setTheme(theme: ThemeValue, setStorage: boolean = true): void {
		this.theme$.next(theme);
		this.updateDocumentStyle(theme);
		if (setStorage) {
			ThemeService.STORAGE.set(theme)
		}
	}

	static getCurrentTheme() {
		const themeFromStorage = this.STORAGE.get();
		return Object.values(Themes).find(it => it?.cssName === themeFromStorage?.cssName) ?? Object.values(Themes)[0];
	}

	protected updateDocumentStyle(newTheme: ThemeValue): void {
		const toCssClass = (value: string) => `${THEME_CSS_PREFIX}${value}`;

		if (newTheme) {
			this.renderer.addClass(document.body, toCssClass(newTheme.cssName));
		}

		for (const theme of Object.values(Themes)) {
			if (theme !== newTheme) {
				this.renderer.removeClass(document.body, toCssClass(theme.cssName));
			}
		}

	}

	getTheme(): Observable<ThemeValue> {
		return this.theme$;
	}
}
