import { AfterViewInit, ChangeDetectorRef, Component, ElementRef, OnDestroy, OnInit, Signal, signal, ViewChild, WritableSignal } from '@angular/core';
import { MediaMatcher } from '@angular/cdk/layout';
import { AuthService } from '@core/service/auth.service';
import { BoundedLocalStorage } from '@core/service/local-storage.service';
import { Router } from '@angular/router';
import { NavItem } from '@core/navigation/sidebar.model';
import { Store } from '@ngrx/store';
import { fromAuthActions, fromConfigActions } from '@store/actions/actions';
import packageJson from '../../package.json';
import { fromConfigSelectors } from '@store/selectors/selectors';
import { Route } from '@shared/constants/routing-paths.constants';
import { take } from 'rxjs';
import { LocalStorageKey } from '@shared/constants/local-storage.constants';
import { SidebarStorage, ViewType } from '@app/app.model';
import { PagesModule } from '@pages/pages.module';
import { ThemeService } from '@core/service/theme.service';
import { Themes } from '@model/common/theme.model';
import { NavItemService } from '@core/service/nav-item.service';

@Component({
	selector: 'app-root',
	templateUrl: './app.component.html',
	styleUrls: ['./app.component.scss'],
	imports: [PagesModule],
})
export class AppComponent implements OnInit, AfterViewInit, OnDestroy {
	mobileQuery: MediaQueryList;
	showSidebar: boolean = false;
	private readonly mobileQuerySize: string = '800px';
	private readonly storage: BoundedLocalStorage<SidebarStorage> = BoundedLocalStorage.create(LocalStorageKey.SIDEBAR);
	readonly version: string = packageJson.version;
	private readonly currentYear: number = new Date().getFullYear();
	readonly copyright: string = packageJson.copyright
		.replace(/{{\s*currentYear\s*}}/, this.currentYear.toString())
		.replace(`${this.currentYear}-${this.currentYear}`, this.currentYear.toString()); // Remove redundant 'from-to' years if it's the same year
	protected readonly ViewType = ViewType;

	@ViewChild('toolbar') toolbar: ElementRef;
	@ViewChild('sidebar') sidebar: ElementRef;
	isAuthenticated: WritableSignal<boolean> = signal(false);
	hasAnyNavItem: Signal<boolean> = this.navItemService.hasAnyNavItem;

	countdownDate: Date = new Date("2026-08-08T16:00:00.000+02:00")

	navItems: NavItem[];

	// Set style for desktop mode
	protected style: 'full-width' | 'page' = 'page';

	constructor(
		private readonly changeDetectorRef: ChangeDetectorRef,
		private readonly media: MediaMatcher,
		private readonly authService: AuthService,
		private readonly router: Router,
		private readonly store: Store,
		private readonly navItemService: NavItemService,
		private readonly themeService: ThemeService,
	) {
		this.themeService.setTheme(Themes.LIGHT);
		this.mobileQuery = media.matchMedia(`(max-width: ${this.mobileQuerySize})`);
		this.mobileQuery.onchange = ($event: MediaQueryListEvent) => {
			this.configureSidebar(() => {
				this.setSidebarStyling();
			}, true);
		};
		this.initShowSidebar();
		this.authService.getUserAuthenticatedSubject().subscribe(authenticated => {
			this.isAuthenticated.set(authenticated);
		})
	}

	ngOnInit(): void {
		this.initializeConfigSubscribers();
		this.navItemService.getNavItemsUpdatedSubject().subscribe((navItems: NavItem[]) => {
			if (navItems.length === 0) {
				this.showSidebar = false;
			} else {
				this.initShowSidebar();
			}
			this.setNavItems(navItems);
		});
		this.getExistingUserSessionIfExists();
	}

	initializeConfigSubscribers(): void {
		this.store.select(fromConfigSelectors.hasInitializedOnce)
			.pipe(take(1))
			.subscribe((hasInitializedOnce: boolean) => {
				if (!hasInitializedOnce) {
					this.store.dispatch(fromConfigActions.fetchContext());
				}
			}).unsubscribe();

		this.store.select(fromConfigSelectors.isFirstTimeSetup).subscribe((isFirstTimeSetup: boolean) => {
			if (isFirstTimeSetup) {
				this.router.navigate([Route.REGISTER]);
			}
		});
	}

	setNavItems(navItems: NavItem[] = []): void {
		this.navItems = navItems;
		this.configureSidebar(() => {
			this.setSidebarStyling();
		}, true);
	}

	ngAfterViewInit(): void {
		this.setSidebarVisibility(true);
	}

	ngOnDestroy(): void { }

	toggleSidebar(): void {
		this.showSidebar = !this.showSidebar;
		this.setSidebarVisibility(false);
	}

	setSidebarVisibility(disableAnimation: boolean = false): void {
		this.persistShowSidebar();

		this.configureSidebar(() => {
			this.setSidebarStyling();
		}, disableAnimation);
	}

	setSidebarStyling(): void {
		if (this.sidebar) {
			const setMarginLeft = (size: string | number) => { this.sidebar.nativeElement.style.marginLeft = size?.toString(); };
			const setMarginTop = (size: string | number) => { this.sidebar.nativeElement.style.marginTop = size?.toString(); };

			const cssClassVisible = 'visible';
			const cssClassHide = 'hidden';
			if (this.showSidebar && !this.sidebarHasCssClass(cssClassVisible)) {
				this.addCssClassToSidebar(cssClassVisible);
				this.removeCssClassToSidebar(cssClassHide);
			} else if (!this.showSidebar && !this.sidebarHasCssClass(cssClassHide)) {
				this.addCssClassToSidebar(cssClassHide);
				this.removeCssClassToSidebar(cssClassVisible);
			}

			if (!this.mobileQuery.matches) { // Desktop
				setMarginLeft(0);
				setMarginTop(0);
			} else { // Mobile
				setMarginLeft(0);
				setMarginTop(this.showSidebar ? 0 : `-${this.sidebar.nativeElement.clientHeight + this.toolbar.nativeElement.clientHeight}px`);
			}
		}
	}

	sidebarHasCssClass(cssClass: string): boolean {
		return this.sidebar?.nativeElement.classList.contains(cssClass) ?? false;
	}

	addCssClassToSidebar(cssClass: string): void {
		this.sidebar?.nativeElement.classList.add(cssClass);
	}

	removeCssClassToSidebar(cssClass: string): void {
		this.sidebar?.nativeElement.classList.remove(cssClass)
	}

	setSidebarAnimationEnabled(enable: boolean): void {
		if (this.sidebar) {
			const transitionClass = 'navigation-bar-transition';
			if (enable && !this.sidebar.nativeElement.classList.contains(transitionClass)) {
				// A small delay is used in order for the "margin" property to be set before the transition is enabled
				setTimeout(() => {
					this.sidebar.nativeElement.classList.add(transitionClass);
				}, 50);
			} else if (!enable) {
				this.sidebar.nativeElement.classList.remove(transitionClass);
			}
		}
	}

	private persistShowSidebar(showSidebar: boolean = this.showSidebar): void {
		this.storage.setItem('isOpened', showSidebar);
	}

	private initShowSidebar(): void {
		this.showSidebar = this.storage.getItem('isOpened') ?? !this.mobileQuery.matches;
	}

	isOnSidebarLink(navItem: NavItem): boolean {
		return this.router.url === navItem.route;
	}

	configureSidebar(configureFn: () => void, disableAnimation: boolean = false) {
		if (disableAnimation) {
			this.setSidebarAnimationEnabled(false);
			this.changeDetectorRef.detectChanges();
		}
		configureFn();
		if (disableAnimation) {
			this.setSidebarAnimationEnabled(true);
		}
		this.changeDetectorRef.detectChanges();
	}

	getExistingUserSessionIfExists(): void {
		const hasTokenInLocalStorage = this.authService.getUserTokenFromLocalStorage();
		if (hasTokenInLocalStorage && !this.authService.shouldRememberSession()) {
			this.authService.removeUserSessionLocally();
		} else if (hasTokenInLocalStorage) {
			this.store.dispatch(fromAuthActions.getUserSession());
		}
	}

}
