import { Directive, effect, ElementRef, input, Renderer2, Signal } from '@angular/core';
import { KeyOfType } from '@shared/util/typing';

type CustomAttribute = KeyOfType<CustomAttributes, Signal<any>>;

@Directive({
	selector: 'data-view, [dataView]'
})
export class CustomAttributes {

	readonly ['data-view'] = input<string>();
	readonly dataView = input<string>();

	constructor(private readonly _elRef: ElementRef, private readonly _renderer: Renderer2) {
		effect(() => {
			this.updateAttributes();
		});
	}

	private updateAttributes() {
		// Add all attributes that shall be exposed in the HTML here!
		this.updateAttribute('data-view', this['data-view']() ?? this.dataView());
	}

	private updateAttribute(attributeName: CustomAttribute, value: any): void {
		if (this[attributeName]) {
			this._renderer.setAttribute(this._elRef.nativeElement, attributeName, value?.toString());
		} else if (this._elRef.nativeElement.getAttribute(attributeName) != null) {
			this._renderer.removeAttribute(this._elRef.nativeElement, attributeName);
		}
	}

}
