import { Injectable } from '@angular/core';
import { environment } from '@env/environment';


@Injectable({
	providedIn: "root"
})
export class Logger {

	public static logGuard(guardName: string, ...elements: any): void {
		if (environment.logger.guard) {
			console.log(`${guardName} (Guard):`, ...elements);
		}
	}

	public static logInterceptor(interceptorName: string, ...elements: any): void {
		if (environment.logger.interceptor) {
			console.log(`${interceptorName} (Interceptor):`, ...elements);
		}
	}

	public static logService(serviceName: string, ...elements: any): void {
		if (environment.logger.service) {
			console.log(`${serviceName} (Service):`, ...elements);
		}
	}

	public static logComponent(componentName: string, ...elements: any): void {
		if (environment.logger.component) {
			console.log(`${componentName} (Component):`, ...elements);
		}
	}

	public static logStoreEffects(storeEffectsName: string, ...elements: any): void {
		if (environment.logger.storeEffects) {
			console.log(`${storeEffectsName} (Store Effects):`, ...elements);
		}
	}

	public static log(...elements: any): void {
		if (environment.logger.other) {
			console.log(...elements);
		}
	}

}
