import { createAction, props } from '@ngrx/store';
import { ContextResponse } from '@model/network/config/config.model';

export const fetchContext = createAction(
	'[Config] Fetch base application context'
);

export const fetchContextSuccess = createAction(
	'[Config] Fetch base application context was successful',
	props<ContextResponse>()
);

export const fetchContextError = createAction(
	'[Config] Fetch base application context got an error',
	props<ContextResponse | Error>()
);
