/**
 * A map where both the key and value can be considered unique, with lookups being possible using either the key or value.
 */
export class TwoWayMap<K, V> extends Map<K, V> {
	private readonly reverseLookup: Map<V, K>;

	constructor(entries?: readonly (readonly [K, V])[] | null) {
		super(entries || []);
		this.reverseLookup = new Map([...(entries || [])].map(([k, v]) => [v, k]));
	}

	override set(key: K, value: V): this {
		// Delete old keys to ensure that any one-way references only would be deleted
		this.reverseLookup?.delete(this.get(key));
		super.delete(this.revGet(value));

		super.set(key, value);
		this.reverseLookup?.set(value, key);
		return this;
	}

	override get(key: K): V | undefined {
		return super.get(key);
	}

	revGet(key: V): K | undefined {
		return this.reverseLookup?.get(key);
	}

	override has(key: K): boolean {
		return super.has(key);
	}

	revHas(key: V): boolean {
		return this.reverseLookup?.has(key) ?? false;
	}

}