import "@extensions/global.extensions";
import { environment } from '@env/environment';
import { CommonUtil } from '@core/util';

/**
 * Route inside the UI (page location)
 */
export class Route {
	public static HOME = "/";
	public static LOGIN = "/login";
	public static LOGOUT = "/logout";
	public static REGISTER = "/register";
	public static SETTINGS = {
		ALL: "/settings"
	};
	public static INFO = "/info";
	public static WEDDING = "/wedding";
	public static DINNER = "/dinner";
	public static PARTY = "/after-party";
	public static CONTACT = "/about-us";

	public static toPath = (path: string): string => {
		return path.removePrefix("/").removeSuffix("/");
	}

	/**
	 * Returns the matched route if parameter is valid, or null if it doesn't exist.
	 * @param route Route to check
	 */
	public static asRoute(route: string): string | null {
		return Object.entries(Route)
			.flatMap(([key, value]) => CommonUtil.isObject(value) ? Object.values(CommonUtil.flattenObject(value)) : [value])
			.filter(value => value === route)[0] ?? null;
	}
}

const API_URL: string = environment.apiUrl;

export class ApiEndpoint {

	// Auth
	public static readonly LOGIN: string = API_URL + "/auth/login";
	public static readonly LOGIN_LOCALHOST: string = API_URL + "/auth/host/login";
	public static readonly LOGOUT: string = API_URL + "/auth/logout";
	public static readonly GET_USER_SESSION: string = API_URL + "/auth/user-session";
	public static readonly REGISTER: string = API_URL + "/auth/register";
	public static readonly MY_INVITES: string = API_URL + "/auth/invite/my";
	public static readonly ALL_INVITES: string = API_URL + "/auth/invite/all";
	public static readonly CREATE_INVITE: string = API_URL + "/auth/invite/create";
	public static readonly USER_SESSION: string = API_URL + "/auth/session";

	// Config
	public static readonly GET_CONFIG: string = API_URL + "/context"

	// Media
	public static readonly GET_STREAM: string = API_URL + "/stream";
}
