import { Injectable } from '@angular/core';
import * as countryLanguages from '@ladjs/country-language';
import { Country, Language } from '@ladjs/country-language';

@Injectable()
export class LocalizationService {

	toLanguageCode(langCodeOrCountry: string): string | undefined {
		let result: Language | undefined = this.getLanguageByCode(langCodeOrCountry);
		if (!result) {
			const country = this.getCountryByCode(langCodeOrCountry);
			if (country) {
				result = this.getLanguageByCode(country?.languages[0]);
			}
		}

		return result?.name?.toLowerCase();
	}

	private getLanguageByCode(code: string): Language | undefined {
		let result = undefined;
		countryLanguages.getLanguage(code, (error, language) => {
			if (language) {
				result = language;
			}
		});

		return result;
	}

	private getCountryByCode(code: string): Country | undefined {
		let result = undefined;
		countryLanguages.getCountry(code, (error, country) => {
			if (country) {
				result = country;
			}
		});

		return result;
	}
}
