import { Injectable } from '@angular/core';
import { Store } from '@ngrx/store';
import { HttpClient } from '@angular/common/http';
import { Observable, tap } from 'rxjs';
import { ApiEndpoint } from '@shared/constants/routing-paths.constants';
import { ContextResponse } from '@model/network/config/config.model';
import { verifyResponseBodyStatus } from '@core/util';

@Injectable({
	providedIn: 'root'
})
export class ConfigService {

	constructor(private store: Store, private http: HttpClient) { }

	getContext(): Observable<ContextResponse> {
		return this.http.get<ContextResponse>(ApiEndpoint.GET_CONFIG).pipe(
			 tap(verifyResponseBodyStatus)
		);
	}

}
